            <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
              {activities.map((act, i) => (
                <div key={i} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: 16, border: '1px solid var(--nu-ink-100)', borderRadius: 8 }}>
