                    <div style={{ fontWeight: 500, marginBottom: 4 }}>{act.name}</div>
                    <div style={{ display: 'flex', gap: 12, fontSize: 12, color: 'var(--nu-ink-500)' }}>
                      <span style={{ display: 'flex', alignItems: 'center', gap: 4 }}><lucide.Target size={12}/> Closes {act.closes_n_reds || 2} reds</span>
                      <span style={{ display: 'flex', alignItems: 'center', gap: 4 }}><lucide.Clock size={12}/> {act.time_commitment || '3 hrs/wk'}</span>
                    </div>
                  </div>
                  <button 
                    className={added.has(act.id) ? "nu-btn-ghost" : "nu-btn-outline"} 
                    style={{ fontSize: 12, padding: '6px 12px' }}
