                ))}
                <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 12, marginTop: 16 }}>
                  <button className="nu-btn-ghost" onClick={() => setShowNudgeModal(false)}>Cancel</button>
                  <button className="nu-btn-primary" onClick={() => { setShowNudgeModal(false); setSelected(new Set()); }}>Approve & Send All</button>
                </div>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

const ScreenTrackComparison = ({ onBack }) => {
  const [isLoading, setIsLoading] = useState(true);
  const [scores, setScores] = useState([]);

  useEffect(() => {
    const fetchScores = async () => {
      try {
        const prompt = `Calculate Predictive Co-op Match Score for 3 tracks. Return JSON.`;
        await callAIWithFallback(prompt, "Calculate match probabilities.", { maxTokens: 300 });
        setScores([
          { id: '1', name: 'Data Analyst Co-op', prob: 82, driver: 'Strong SQL Fluency' },
          { id: '2', name: 'Product Analyst Co-op', prob: 68, driver: 'Missing Stakeholder Comm' },
          { id: '3', name: 'Software Engineer Co-op', prob: 45, driver: 'Missing Version Control' }
        ]);
      } finally {
        setIsLoading(false);
      }
    };
    fetchScores();
  }, []);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
      <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end' }}>
        <div>
          <h1 className="spectral-semibold" style={{ fontSize: 28, margin: '0 0 8px 0' }}>Compare Co-op Tracks</h1>
          <button className="nu-btn-ghost" onClick={onBack} style={{ padding: 0 }}><lucide.ArrowLeft size={16}/> Return to Dashboard</button>
        </div>
      </header>

      {isLoading ? (
        <div className="p-compare">
          {Array(3).fill(0).map((_,i) => <div key={i} className="skeleton" style={{ height: 400 }} />)}
        </div>
      ) : (
        <section className="p-compare">
          {scores.map((score, i) => (
            <motion.div 
              key={score.id} 
              className="compare-col"
              initial={{ opacity: 0, x: 20 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: i * 0.1 }}
              style={{ border: i === 0 ? '2px solid var(--nu-accent)' : 'none' }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                <h2 className="roboto" style={{ fontSize: 18, margin: 0 }}>{score.name}</h2>
                {i === 0 && <span style={{ background: 'var(--nu-accent-tint)', color: 'var(--nu-accent)', padding: '4px 8px', borderRadius: 4, fontSize: 12, fontWeight: 600 }}>Closest Fit</span>}
              </div>
              <div style={{ fontSize: 32, fontFamily: 'var(--font-display)', color: i === 0 ? 'var(--nu-accent)' : 'var(--nu-ink-900)' }}>
                {score.prob}% Match
              </div>
              <p style={{ fontSize: 14, color: 'var(--nu-ink-500)', margin: 0 }}>Key driver: {score.driver}</p>

              <div className="mini-grid" style={{ flexWrap: 'wrap', gap: 4, marginTop: 16 }}>
                {Array(12).fill(0).map((_,j) => (
                  <div key={j} className={`mini-tile ${j < (100-score.prob)/10 ? 'red' : 'green'}`} style={{ width: 24, height: 24, borderRadius: 4 }} />
                ))}
              </div>

              <div style={{ flex: 1 }} />
              <button className={i === 0 ? "nu-btn-primary" : "nu-btn-outline"} style={{ width: '100%' }} onClick={onBack}>Set as Target</button>
            </motion.div>
          ))}
        </section>
      )}
    </div>
  );
};

const ScreenExportStory = ({ onBack }) => {
  const [isLoading, setIsLoading] = useState(true);
  const [story, setStory] = useState(null);
  const [saved, setSaved] = useState(false);

  useEffect(() => {
    const generate = async () => {
      try {
        const prompt = `Synthesize the student's semester of CLR records into a narrative summary. Use Verbalized Sampling.`;
        const res = await callAIWithVS(prompt, "Write narrative.", { maxTokens: 500 });
        const parsed = parseAIJson(res.text, {
          narrative: ["Over the Fall 2025 semester, Maya demonstrated consistent growth in analytical and communication competencies.", "By actively participating in the Husky Data Club and completing the DS 2000 coursework, she closed critical gaps in SQL Fluency and Quantitative Analysis."],
          bullets: ["Applied statistical reasoning to interpret structured data via DS 2000.", "Collaborated cross-functionally in Husky Data Club workshops."]
        });
        setStory(parsed);
      } finally {
        setIsLoading(false);
      }
    };
    generate();
  }, []);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
      <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end' }}>
        <div>
          <h1 className="spectral-semibold" style={{ fontSize: 28, margin: '0 0 8px 0' }}>Your Growth Story</h1>
          <button className="nu-btn-ghost" onClick={onBack} style={{ padding: 0 }}><lucide.ArrowLeft size={16}/> Return to Dashboard</button>
        </div>
        <button className="nu-btn-primary" onClick={() => setSaved(true)} disabled={saved}>
          {saved ? <><lucide.Check size={16}/> Saved</> : <><lucide.Download size={16}/> Save to OneDrive</>}
        </button>
      </header>

      {isLoading ? (
        <div className="skeleton" style={{ height: 600, maxWidth: 800, margin: '0 auto', width: '100%' }} />
      ) : (
        <motion.section 
          className="p-reader"
          initial={{ opacity: 0, rotateX: 10 }}
          animate={{ opacity: 1, rotateX: 0 }}
          transition={{ duration: 0.5 }}
        >
          <div style={{ height: 120, background: 'var(--nu-ink-100)', marginBottom: 32, borderRadius: 4, position: 'relative', overflow: 'hidden' }}>
            <div style={{ position: 'absolute', bottom: 0, left: 0, right: 0, height: 4, background: 'var(--nu-accent)' }} />
            <div style={{ padding: 24, color: 'var(--nu-ink-500)', fontFamily: 'var(--font-mono)', fontSize: 12 }}>Northeastern University · Comprehensive Learner Record</div>
          </div>
          <h2>Maya Chen - Fall 2025</h2>

          <div style={{ marginBottom: 32 }}>
            <h3 className="roboto" style={{ fontSize: 14, textTransform: 'uppercase', color: 'var(--nu-ink-500)', letterSpacing: '0.05em' }}>Executive Summary</h3>
            {story?.narrative?.map((p, i) => <p key={i}>{p}</p>)}
          </div>

          <div className="p-time-machine" style={{ marginBottom: 32, padding: 24, background: 'var(--nu-canvas)', borderRadius: 8 }}>
            <h3 className="roboto" style={{ fontSize: 14, textTransform: 'uppercase', color: 'var(--nu-ink-500)', letterSpacing: '0.05em', marginBottom: 16 }}>Trajectory</h3>
            <div style={{ display: 'flex', alignItems: 'center', gap: 16 }}>
              <div style={{ flex: 1, height: 2, background: 'linear-gradient(90deg, var(--fluent-red), var(--fluent-amber), var(--fluent-green))' }} />
              <span style={{ fontFamily: 'var(--font-mono)', fontSize: 12, color: 'var(--fluent-green)' }}>+4 Competencies</span>
            </div>
          </div>

          <div>
            <h3 className="roboto" style={{ fontSize: 14, textTransform: 'uppercase', color: 'var(--nu-ink-500)', letterSpacing: '0.05em' }}>Resume Bullets</h3>
            <ul style={{ paddingLeft: 20 }}>
              {story?.bullets?.map((b, i) => <li key={i}>{b}</li>)}
            </ul>
          </div>
        </motion.section>
      )}
    </div>
  );
};

// --- APP ROOT ---
const App = () => {
  const [hasConsented, setHasConsented] = useState(false);
  const [activeTab, setActiveTab] = useState('My Co-op Readiness');
  const [currentView, setCurrentView] = useState('dashboard');
  const [drilldownComp, setDrilldownComp] = useState(null);
  const [demoMode, setDemoMode] = useState('standard');

  useEffect(() => {
    injectStyles();
    if (sessionStorage.getItem('nu_ferpa_consent') === 'true') {
      setHasConsented(true);
    }
  }, []);

  const handleConsent = () => {
    sessionStorage.setItem('nu_ferpa_consent', 'true');
    setHasConsented(true);
  };

  const renderContent = () => {
    if (!hasConsented) return <ScreenFerpaConsent onConsent={handleConsent} />;

    if (demoMode === 'non-student') {
      return (
        <div style={{ padding: 48, textAlign: 'center' }}>
          <lucide.UserX size={48} color="var(--nu-ink-300)" style={{ margin: '0 auto 16px' }} />
          <h2 className="spectral-semibold">No Student Record Found</h2>
          <p className="roboto" style={{ color: 'var(--nu-ink-500)' }}>Are you logged in with your student account? If you are staff or an employer, you do not have a Co-op Readiness dashboard.</p>
        </div>
      );
    }

    if (activeTab === 'Advisor Heatmap') return <ScreenAdvisorHeatmap />;

    if (currentView === 'compare') return <ScreenTrackComparison onBack={() => setCurrentView('dashboard')} />;
    if (currentView === 'export') return <ScreenExportStory onBack={() => setCurrentView('dashboard')} />;

    return (
      <>
        <ScreenStudentDashboard 
          onDrilldown={setDrilldownComp} 
          onCompare={() => setCurrentView('compare')}
          onExport={() => setCurrentView('export')}
          isZeroActivityMode={demoMode === 'zero-activity'}
        />
        {drilldownComp && <ModalDrilldown competency={drilldownComp} onClose={() => setDrilldownComp(null)} />}
      </>
    );
  };

  return (
    <div style={{ minHeight: '100vh', background: 'var(--nu-canvas)' }}>
      <TeamsChrome activeTab={activeTab} onTabChange={setActiveTab}>
        {renderContent()}
      </TeamsChrome>

      {/* Demo Controls */}
      <div className="demo-controls">
        <div style={{ fontSize: 10, textTransform: 'uppercase', letterSpacing: '0.05em', opacity: 0.7 }}>Demo Controls</div>
        <select 
          value={!hasConsented ? 'ferpa' : activeTab === 'Advisor Heatmap' ? 'advisor' : currentView}
          onChange={(e) => {
            const v = e.target.value;
            setDemoMode('standard');
            if (v === 'ferpa') { sessionStorage.removeItem('nu_ferpa_consent'); setHasConsented(false); }
            else if (v === 'advisor') { setHasConsented(true); setActiveTab('Advisor Heatmap'); }
            else { setHasConsented(true); setActiveTab('My Co-op Readiness'); setCurrentView(v); }
          }}
        >
          <option value="ferpa">1. FERPA Consent</option>
          <option value="dashboard">2. Student Dashboard</option>
          <option value="compare">3. Track Comparison</option>
          <option value="advisor">4. Advisor Heatmap</option>
          <option value="export">5. Export Story</option>
        </select>
        <select value={demoMode} onChange={e => setDemoMode(e.target.value)}>
          <option value="standard">Standard User</option>
          <option value="zero-activity">Zero Activities</option>
          <option value="non-student">Non-Student Account</option>
        </select>
      </div>
    </div>
  );
};

// --- VERIFICATION ---
function __test_state_transitions__() {
  console.assert(typeof App === 'function', 'App must be a component');
  return true;
}
if (typeof window !== 'undefined') {
  window.__hicProtoTests = __test_state_transitions__;
}

