// --- AI HELPERS ---
async function callAIWithFallback(systemPrompt, userPrompt, opts = {}) {
  const providers = [
    {
      name: 'gemini',
      url: '/api/ai/gemini-compat',
      headers: { 'Content-Type': 'application/json', 'x-openai-endpoint': 'chat' },
      body: {
        model: 'gemini-3.1-pro-preview',
        messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: userPrompt }],
        temperature: opts.temperature ?? 0.3,
        max_tokens: opts.maxTokens ?? 1200,
      },
      extract: (data) => data?.choices?.[0]?.message?.content,
    },
    {
      name: 'anthropic',
      url: '/api/ai/anthropic',
      headers: { 'Content-Type': 'application/json' },
      body: {
        model: 'claude-opus-4-6',
        max_tokens: opts.maxTokens ?? 1200,
        system: systemPrompt,
        messages: [{ role: 'user', content: userPrompt }],
      },
      extract: (data) => data?.content?.[0]?.text,
    },
    {
      name: 'openai',
      url: '/api/ai/openai',
      headers: { 'Content-Type': 'application/json' },
      body: {
        model: 'gpt-4o',
        messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: userPrompt }],
        temperature: opts.temperature ?? 0.3,
      },
      extract: (data) => data?.choices?.[0]?.message?.content,
    }
  ];

  let lastErr = null;
  for (const p of providers) {
    try {
      const res = await fetch(p.url, { method: 'POST', headers: p.headers, body: JSON.stringify(p.body) });
      if (!res.ok) throw new Error(`${p.name} HTTP ${res.status}`);
      const data = await res.json();
      const text = p.extract(data);
      if (!text) throw new Error(`${p.name} returned empty`);
      return { text, provider: p.name };
    } catch (e) {
      lastErr = e;
      console.warn(`[AI] ${p.name} failed:`, e);
    }
  }
  throw new Error(`All AI providers failed. Last error: ${lastErr?.message}`);
}

async function callAIWithVS(systemPrompt, userPrompt, opts = {}) {
  const VS_INSTRUCTION = `
Before answering, generate FIVE distinct candidate responses with diverse framings. Assign each a probability mass reflecting how likely a typical model would emit it. Then return the candidate with the LOWEST probability that still earns ≥7/10 on quality and grounded relevance. 
Output ONLY the final chosen candidate in the requested JSON format. Do not show the intermediate candidates or markdown fences.
`.trim();
  return callAIWithFallback(`${systemPrompt}\n\n${VS_INSTRUCTION}`, userPrompt, { ...opts, temperature: 0.85 });
}

// Helper to safely parse JSON from AI
const parseAIJson = (text, fallback) => {
  try {
    const cleaned = text.replace(/```json/g, '').replace(/```/g, '').trim();
    return JSON.parse(cleaned);
  } catch (e) {
    console.error("Failed to parse AI JSON:", text);
    return fallback;
  }
};

