const ScreenStudentDashboard = ({ onDrilldown, onCompare, onExport, isZeroActivityMode }) => {
  const [isLoading, setIsLoading] = useState(true);
  const [tiles, setTiles] = useState([]);
  const [summary, setSummary] = useState("");
  const [recs, setRecs] = useState([]);
  const [alts, setAlts] = useState([]);
  const [showAlts, setShowAlts] = useState(false);
  const [hoveredTile, setHoveredTile] = useState(null);
  const [touchRevealed, setTouchRevealed] = useState(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const [addedRecs, setAddedRecs] = useState(new Set());

  const loadData = useCallback(async (isSimulatedSync = false) => {
    setIsLoading(!isSimulatedSync);
    try {
      if (isZeroActivityMode) {
        setTiles([]);
        setSummary("You haven't logged any CLR activities yet. Check out the recommended starter activities below to get on the board.");
        setRecs([{ id: '1', action: 'Attend First-Year Orientation Workshop', rationale: 'Great starting point' }]);
        setAlts([]);
        return;
      }

      // 1. Gap Ranking (Deterministic mock for speed, but structured like AI output)
      const baseTiles = SEED_COMPETENCIES.slice(0, 12).map((c, i) => ({
        id: c.id,
        name: c.name,
        status: i < 4 ? 'red' : i < 8 ? 'amber' : 'green',
        current: i < 4 ? 2 : i < 8 ? 4 : c.threshold,
        threshold: c.threshold
      }));

      if (isSimulatedSync) {
        baseTiles[0].status = 'green';
        baseTiles[0].current = baseTiles[0].threshold;
      }
      setTiles(baseTiles);

      // 2. Copilot Summary
      const summaryPrompt = `You are Copilot for Power BI. Summarize the student's current competency gap state in exactly two sentences. Be calm, encouraging, and jargon-free. Do not use formatting.`;
      const summaryUser = `Current state: ${isSimulatedSync ? '1 less red gap, Quant Analysis is green' : '4 red gaps, 4 amber, 4 green'}. Target track: Data Analyst Co-op.`;
      const summaryRes = await callAIWithFallback(summaryPrompt, summaryUser, { maxTokens: 100 });
      setSummary(parseAIJson(summaryRes.text, { headline: summaryRes.text }).headline || summaryRes.text);

      // 3. Recommender (VS)
      const recPrompt = `You are an academic advisor AI. Suggest two concrete, time-boxed actions to close the student's largest gaps. Provide two alternative pairs with probability scores.`;
      const recUser = `Largest gaps: ${baseTiles.filter(t=>t.status==='red').map(t=>t.name).join(', ')}. Availability: 6 hrs/wk.`;
      const recRes = await callAIWithVS(recPrompt, recUser);
      const parsedRecs = parseAIJson(recRes.text, {
        top_recommendations: [{ id: '1', action: 'Join NUImpact Consulting Group', rationale: 'Closes 3 reds' }],
        alternatives: [{ id: '2', action: 'Attend SQL Workshop', probability: 45 }]
      });
      setRecs(parsedRecs.top_recommendations || []);
      setAlts(parsedRecs.alternatives || []);

    } catch (e) {
      console.error(e);
      setSummary("Your dashboard is up to date. Review your tiles below.");
    } finally {
      setIsLoading(false);
      if (isSimulatedSync) setTimeout(() => setIsSyncing(false), 1000);
    }
  }, [isZeroActivityMode]);

  useEffect(() => { loadData(); }, [loadData]);

  const handleSimulateSync = () => {
    setIsSyncing(true);
    setTimeout(() => loadData(true), 600);
  };

  const handleAddCalendar = (id) => {
    setAddedRecs(prev => new Set(prev).add(id));
  };

  if (isLoading) return (
    <div className="dashboard-grid">
      <div className="p-info-matrix">
        {Array(12).fill(0).map((_,i) => <div key={i} className="comp-tile skeleton" />)}
