                {addedRecs.has(rec.id) ? 'Added' : 'Add to Outlook'}
              </button>
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
      <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', flexWrap: 'wrap', gap: 16 }}>
        <div>
          <h1 className="spectral-semibold" style={{ fontSize: 28, margin: '0 0 8px 0' }}>My Co-op Readiness</h1>
          <div style={{ color: 'var(--nu-ink-500)', fontSize: 14, display: 'flex', alignItems: 'center', gap: 8 }}>
