const ScreenAdvisorHeatmap = () => {
  const [students, setStudents] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [selected, setSelected] = useState(new Set());
  const [showNudgeModal, setShowNudgeModal] = useState(false);
  const [drafts, setDrafts] = useState([]);
  const [isDrafting, setIsDrafting] = useState(false);
  const [search, setSearch] = useState('');
  const [sortCol, setSortCol] = useState('velocity');

  useEffect(() => {
    const loadCohort = async () => {
      try {
        const prompt = `Analyze cohort velocities. Flag students stalled (velocity < 2). Return JSON array.`;
        await callAIWithFallback(prompt, "Identify anomalies.", { maxTokens: 200 });
        setStudents(SEED_STUDENTS);
      } finally {
        setIsLoading(false);
      }
    };
    loadCohort();
  }, []);

  const toggleSelect = (id) => {
    const next = new Set(selected);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setSelected(next);
  };

  const handleNudge = async () => {
    setShowNudgeModal(true);
    setIsDrafting(true);
    try {
      const prompt = `Draft personalized Teams DMs for students. Reference their gaps. Use Verbalized Sampling to pick the best tone.`;
      const res = await callAIWithVS(prompt, `Draft for ${selected.size} students.`);
      const parsed = parseAIJson(res.text, {
        drafts: Array.from(selected).map(id => ({
          id,
          student_name: students.find(s=>s.id===id)?.name,
          message_body: `Hi, I noticed your gap closure has stalled recently. Let's chat about your co-op readiness.`
        }))
      });
      setDrafts(parsed.drafts || []);
    } finally {
      setIsDrafting(false);
    }
  };

  const filteredStudents = students
    .filter(s => s.name.toLowerCase().includes(search.toLowerCase()))
    .sort((a, b) => {
      if (sortCol === 'velocity') return a.velocity_14d - b.velocity_14d;
      if (sortCol === 'name') return a.name.localeCompare(b.name);
      return 0;
    });

  if (isLoading) return <div className="skeleton" style={{ height: 400, margin: 32 }} />;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
      <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', flexWrap: 'wrap', gap: 16 }}>
        <div>
          <h1 className="spectral-semibold" style={{ fontSize: 28, margin: '0 0 8px 0' }}>Cohort Heatmap: Khoury First-Years</h1>
          <div style={{ color: 'var(--nu-ink-500)', fontSize: 14 }}>38 Advisees · Default Filter: Students at Risk</div>
        </div>
        <input 
          type="text" 
          placeholder="Search students..." 
          value={search} 
          onChange={e => setSearch(e.target.value)} 
          style={{ padding: '8px 12px', borderRadius: 4, border: '1px solid var(--nu-ink-300)', width: 250 }}
        />
      </header>

      <section className="p-cohort" style={{ overflowX: 'auto' }}>
        <table style={{ minWidth: 800 }}>
          <thead>
            <tr>
              <th style={{ width: 40 }}><input type="checkbox" onChange={(e) => setSelected(e.target.checked ? new Set(filteredStudents.map(s=>s.id)) : new Set())} /></th>
              <th onClick={() => setSortCol('name')} style={{ cursor: 'pointer' }}>Student {sortCol === 'name' && '↓'}</th>
              <th>Target Track</th>
              <th onClick={() => setSortCol('velocity')} style={{ cursor: 'pointer' }}>Velocity (14d) {sortCol === 'velocity' && '↓'}</th>
              <th>Gap Profile</th>
            </tr>
          </thead>
          <tbody>
            {filteredStudents.map(stu => (
              <tr key={stu.id} className={selected.has(stu.id) ? 'selected' : ''}>
                <td><input type="checkbox" checked={selected.has(stu.id)} onChange={() => toggleSelect(stu.id)} /></td>
                <td>
                  <div style={{ fontWeight: 500 }}>{stu.name}</div>
                  {stu.at_risk_flag && <span style={{ fontSize: 10, background: 'var(--fluent-red)', color: 'white', padding: '2px 6px', borderRadius: 4, marginTop: 4, display: 'inline-block' }}>Stalled</span>}
                </td>
                <td style={{ color: 'var(--nu-ink-500)' }}>{stu.target_track}</td>
                <td>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                    <span style={{ width: 20, fontFamily: 'var(--font-mono)' }}>{stu.velocity_14d}</span>
                    <div style={{ width: 60, height: 16, background: 'var(--nu-ink-100)', borderRadius: 2, overflow: 'hidden' }}>
                      <div style={{ height: '100%', width: `${Math.min(100, stu.velocity_14d * 10)}%`, background: stu.velocity_14d < 2 ? 'var(--fluent-red)' : 'var(--fluent-green)' }} />
                    </div>
                  </div>
                </td>
                <td>
                  <div className="mini-grid">
                    {Array(12).fill(0).map((_,i) => (
                      <div key={i} className={`mini-tile ${i < (stu.gap_score_pct/10) ? 'red' : i < 8 ? 'amber' : 'green'}`} />
                    ))}
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </section>

      <AnimatePresence>
        {selected.size > 0 && (
          <motion.div 
            initial={{ y: 100 }} animate={{ y: 0 }} exit={{ y: 100 }}
            style={{ position: 'fixed', bottom: 48, left: '50%', transform: 'translateX(-50%)', background: 'var(--nu-surface)', padding: '16px 24px', borderRadius: 8, boxShadow: 'var(--shadow-lift)', display: 'flex', alignItems: 'center', gap: 24, zIndex: 100 }}
          >
            <span style={{ fontWeight: 500 }}>{selected.size} students selected</span>
            <button className="nu-btn-primary" onClick={handleNudge}><lucide.MessageSquare size={16}/> Send encouragement nudge</button>
          </motion.div>
        )}
      </AnimatePresence>

      {showNudgeModal && (
        <div className="modal-overlay" onClick={() => setShowNudgeModal(false)}>
          <div className="modal-content p-hitl" onClick={e => e.stopPropagation()} style={{ maxWidth: 800 }}>
            <h2 className="spectral-semibold" style={{ margin: '0 0 24px 0' }}>Review Drafts</h2>
            {isDrafting ? (
              <div className="skeleton" style={{ height: 200 }} />
            ) : (
              <div className="p-vignette-trio" style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
                {drafts.map(draft => (
                  <div key={draft.id} style={{ border: '1px solid var(--nu-ink-100)', padding: 16, borderRadius: 8 }}>
                    <div style={{ fontWeight: 500, marginBottom: 8 }}>To: {draft.student_name}</div>
                    <textarea 
                      style={{ width: '100%', height: 80, padding: 8, borderRadius: 4, border: '1px solid var(--nu-ink-300)', fontFamily: 'var(--font-body)', resize: 'vertical' }}
                      defaultValue={draft.message_body}
                    />
                  </div>
                ))}
                <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 12, marginTop: 16 }}>
                  <button className="nu-btn-ghost" onClick={() => setShowNudgeModal(false)}>Cancel</button>
                  <button className="nu-btn-primary" onClick={() => { setShowNudgeModal(false); setSelected(new Set()); }}>Approve & Send All</button>
                </div>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

