// --- APP ROOT ---
const App = () => {
  const [hasConsented, setHasConsented] = useState(false);
  const [activeTab, setActiveTab] = useState('My Co-op Readiness');
  const [currentView, setCurrentView] = useState('dashboard');
  const [drilldownComp, setDrilldownComp] = useState(null);
  const [demoMode, setDemoMode] = useState('standard');

  useEffect(() => {
    injectStyles();
    if (sessionStorage.getItem('nu_ferpa_consent') === 'true') {
      setHasConsented(true);
    }
  }, []);

  const handleConsent = () => {
    sessionStorage.setItem('nu_ferpa_consent', 'true');
    setHasConsented(true);
  };

  const renderContent = () => {
    if (!hasConsented) return <ScreenFerpaConsent onConsent={handleConsent} />;

    if (demoMode === 'non-student') {
      return (
        <div style={{ padding: 48, textAlign: 'center' }}>
          <lucide.UserX size={48} color="var(--nu-ink-300)" style={{ margin: '0 auto 16px' }} />
          <h2 className="spectral-semibold">No Student Record Found</h2>
          <p className="roboto" style={{ color: 'var(--nu-ink-500)' }}>Are you logged in with your student account? If you are staff or an employer, you do not have a Co-op Readiness dashboard.</p>
        </div>
      );
    }

    if (activeTab === 'Advisor Heatmap') return <ScreenAdvisorHeatmap />;

    if (currentView === 'compare') return <ScreenTrackComparison onBack={() => setCurrentView('dashboard')} />;
    if (currentView === 'export') return <ScreenExportStory onBack={() => setCurrentView('dashboard')} />;

    return (
      <>
        <ScreenStudentDashboard 
          onDrilldown={setDrilldownComp} 
          onCompare={() => setCurrentView('compare')}
          onExport={() => setCurrentView('export')}
          isZeroActivityMode={demoMode === 'zero-activity'}
        />
        {drilldownComp && <ModalDrilldown competency={drilldownComp} onClose={() => setDrilldownComp(null)} />}
      </>
    );
  };

  return (
    <div style={{ minHeight: '100vh', background: 'var(--nu-canvas)' }}>
      <TeamsChrome activeTab={activeTab} onTabChange={setActiveTab}>
        {renderContent()}
      </TeamsChrome>

      {/* Demo Controls */}
      <div className="demo-controls">
        <div style={{ fontSize: 10, textTransform: 'uppercase', letterSpacing: '0.05em', opacity: 0.7 }}>Demo Controls</div>
        <select 
          value={!hasConsented ? 'ferpa' : activeTab === 'Advisor Heatmap' ? 'advisor' : currentView}
          onChange={(e) => {
            const v = e.target.value;
            setDemoMode('standard');
            if (v === 'ferpa') { sessionStorage.removeItem('nu_ferpa_consent'); setHasConsented(false); }
            else if (v === 'advisor') { setHasConsented(true); setActiveTab('Advisor Heatmap'); }
            else { setHasConsented(true); setActiveTab('My Co-op Readiness'); setCurrentView(v); }
          }}
        >
          <option value="ferpa">1. FERPA Consent</option>
          <option value="dashboard">2. Student Dashboard</option>
          <option value="compare">3. Track Comparison</option>
          <option value="advisor">4. Advisor Heatmap</option>
          <option value="export">5. Export Story</option>
        </select>
        <select value={demoMode} onChange={e => setDemoMode(e.target.value)}>
          <option value="standard">Standard User</option>
          <option value="zero-activity">Zero Activities</option>
          <option value="non-student">Non-Student Account</option>
        </select>
      </div>
    </div>
  );
};

